// Loads the hand-written Deep Cases into public.deep_cases.
//
// The cases are bundled in ./data (generated by scripts/cases/export_loader.py from scripts/cases/<market>/),
// so loading them needs no SQL pasting: deploy this function, then call it once.
//
//   GET  -> what would change, per market (writes nothing)
//   POST -> upserts every case that is missing or whose content changed, then checks 3 cases per day
//
// It needs no sign-in on purpose: it can only write the case content bundled with it, and only rows whose
// content fingerprint differs, so a second call writes nothing. The table itself comes from a migration
// (scripts/cases/supabase/deep_cases_schema.sql).
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { DEEP_CASES } from "./data/index.ts";
import { batches, dayProblems, rowsToWrite, type CaseRow, type StoredRow } from "./plan.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body, null, 2), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  if (req.method !== "GET" && req.method !== "POST") return json({ error: "Use GET to preview or POST to load." }, 405);

  try {
    const db = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    const write = req.method === "POST";
    // The API returns at most 1,000 rows per request, so read each market a page at a time.
    const storedRows = async (market: string): Promise<{ rows: StoredRow[]; error?: string }> => {
      const rows: StoredRow[] = [];
      for (let from = 0; ; from += 1000) {
        const { data, error } = await db.from("deep_cases").select("market_id, day, slot, tags")
          .eq("market_id", market).order("day").order("slot").range(from, from + 999);
        if (error) return { rows, error: error.message };
        rows.push(...((data ?? []) as StoredRow[]));
        if (!data || data.length < 1000) return { rows };
      }
    };
    const report: Record<string, { bundled: number; written: number; alreadyCurrent: number }> = {};

    for (const [market, bundledRows] of Object.entries(DEEP_CASES)) {
      const bundled = bundledRows as CaseRow[];
      const { rows: stored, error } = await storedRows(market);
      if (error) {
        const missingTable = /deep_cases/.test(error) && /(does not exist|schema cache|not find)/i.test(error);
        return json({
          error: missingTable
            ? "The deep_cases table does not exist yet. Run scripts/cases/supabase/deep_cases_schema.sql as a migration first."
            : error,
        }, 400);
      }
      const pending = rowsToWrite(bundled, stored);
      if (write) {
        const now = new Date().toISOString();
        for (const batch of batches(pending)) {
          const { error: upsertError } = await db
            .from("deep_cases")
            .upsert(batch.map(row => ({ ...row, updated_at: now })), { onConflict: "market_id,day,slot" });
          if (upsertError) return json({ error: `${market}: ${upsertError.message}`, report }, 500);
        }
      }
      report[market] = { bundled: bundled.length, written: write ? pending.length : 0, alreadyCurrent: bundled.length - pending.length };
    }

    // The same check the SQL editor query runs: every covered day holds exactly three cases.
    const all: StoredRow[] = [];
    for (const market of Object.keys(DEEP_CASES)) {
      const { rows, error } = await storedRows(market);
      if (error) return json({ error, report }, 500);
      all.push(...rows);
    }
    const problems = dayProblems(all);
    const totals: Record<string, number> = {};
    for (const row of all) totals[row.market_id] = (totals[row.market_id] ?? 0) + 1;

    return json({ mode: write ? "loaded" : "preview (POST to load)", report, totalsInDatabase: totals, daysWithoutThreeCases: problems });
  } catch (err) {
    return json({ error: err instanceof Error ? err.message : String(err) }, 500);
  }
});
